A client could request an extremely large number of records and create unnecessary database and memory load.

FastAPI can constrain the parameter:

from fastapi import Query

@app.get("/items")
def items(
    page_size: int = Query(default=100, ge=1, le=500)
):
    return database.load_items(limit=page_size)

For large datasets, use proper pagination rather than returning everything at once.

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

# Example usage:
result = binary_search([1, 2, 3, 4, 5], 3)
print(f"Index: {result}")

